const formData = $('Form Trigger').item.json;
const firecrawlData = $('Firecrawl - Scrape Website').item.json;
const tavilyData = $('Tavily - Recent News Search').item.json;

const websiteContent = firecrawlData?.data?.markdown || firecrawlData?.markdown || 'No website content extracted.';
const newsResults = tavilyData?.results || [];
const newsText = newsResults.map((r, i) => `${i+1}. [${r.title}](${r.url})\n   ${r.content?.substring(0, 300) || ''}...`).join('\n\n');

const mergedContext = `
=== FORM INPUT ===
Company Website: ${formData['Company Website URL']}
Company Name: ${formData['Company Name'] || 'Not provided'}
Contact Name: ${formData['Contact Name'] || 'Not provided'}
Meeting Purpose: ${formData['Meeting Purpose'] || 'Not provided'}
Additional Notes: ${formData['Additional Notes'] || 'None'}

=== WEBSITE CONTENT ===
${websiteContent.substring(0, 6000)}

=== RECENT NEWS (Last 6 months) ===
${newsText || 'No recent news found.'}
`;

return [{ json: { mergedContext, formData } }];

const aiResponse = $('OpenAI - Generate Meeting Brief').item.json;
const formData = $('Prepare Research Context').item.json.formData;

// AI JSON output
const ai = aiResponse.message.content || {};

const now = new Date();

const dateStr = now.toLocaleDateString('en-IN', {
  day: '2-digit',
  month: 'long',
  year: 'numeric'
});

const timeStr = now.toLocaleTimeString('en-IN', {
  hour: '2-digit',
  minute: '2-digit'
});

const isoDate = now.toISOString();

const companyName = formData['Company Name'] || 'Company';
const contactName = formData['Contact Name'] || 'N/A';
const meetingPurpose = formData['Meeting Purpose'] || 'Meeting';

const deliveryChannels =
  formData['Delivery Channels'] ||
  'Email + PDF + Notion + WhatsApp + Slack (All)';

// ---------------- AI Fields ----------------

const executiveSummary = ai.executiveSummary || 'N/A';

const companyOverview = ai.companyOverview || 'N/A';

const productsServices = (ai.productsServices || []).join(', ');

const recentNews = (ai.recentNews || [])
  .map(news => `
📰 <strong>${news.title}</strong><br><br>

${news.summary}<br><br>

<b>Source:</b><br>
<a href="${news.link}">${news.link}</a>
`)
  .join('<hr style="margin:20px 0;">');

const competitors = (ai.competitors || []).join('\n');

const opportunities = (ai.opportunities || []).join('\n');

const risks = (ai.risks || []).join('\n');

const meetingObjectives = (ai.meetingObjectives || []).join('\n');

const suggestedQuestions = (ai.suggestedQuestions || []).join('\n');

const iceBreakers = (ai.iceBreakers || []).join('\n');

const decisionMakers = (ai.decisionMakers || []).join('\n');

const nextSteps = (ai.nextSteps || []).join('\n');

const fullMeetingBrief = ai.fullMeetingBrief || 'N/A';

// ---------------- Delivery Channels ----------------

const useAll = deliveryChannels.includes('All');

const usePDF = useAll || deliveryChannels.includes('PDF');

const useNotion = useAll || deliveryChannels.includes('Notion');

const useWhatsApp =
  (useAll || deliveryChannels.includes('WhatsApp')) &&
  !!formData['Your WhatsApp Number'];

const useSlack =
  useAll || deliveryChannels.includes('Slack');

// ---------------- WhatsApp Summary ----------------

const whatsAppSummary = `🧠 *Meeting Brief Ready*

*Company:* ${companyName}
*Contact:* ${contactName}
*Purpose:* ${meetingPurpose}
*Date:* ${dateStr}

📋 *Executive Summary:*
${executiveSummary.substring(0, 400)}

🎯 *Top Opportunities:*
${opportunities.substring(0, 300)}

✅ Full report generated successfully.`;

// ---------------- Slack Summary ----------------

const slackMessage = `*🧠 New Meeting Brief Generated*

*Company:* ${companyName}
*Contact:* ${contactName}
*Meeting Purpose:* ${meetingPurpose}
*Generated:* ${dateStr} at ${timeStr}

*Executive Summary:*
${executiveSummary.substring(0, 500)}

*Top Opportunities:*
${opportunities.substring(0, 400)}

_Full report has been generated._`;

// ---------------- Return ----------------

return [
  {
    json: {
      generatedAt: isoDate,
      dateStr,
      timeStr,

      formData,

      companyName,
      contactName,
      meetingPurpose,

      executiveSummary,
      companyOverview,
      productsServices,
      recentNews,
      competitors,
      risks,
      opportunities,
      meetingObjectives,
      suggestedQuestions,
      iceBreakers,
      decisionMakers,
      nextSteps,
      fullMeetingBrief,

      reportMarkdown: fullMeetingBrief,

      usePDF,
      useNotion,
      useWhatsApp,
      useSlack,

      whatsAppSummary,
      slackMessage
    }
  }
];

// Generate styled HTML for PDF conversion
const data = $('Format & Prepare All Channels').item.json;
const md = data.reportMarkdown;
const now = data.dateStr + ' at ' + data.timeStr;

// Convert basic markdown to HTML
let html = md
  .replace(/^# (.*?)$/gm, '<h1>$1</h1>')
  .replace(/^## (.*?)$/gm, '<h2>$1</h2>')
  .replace(/^### (.*?)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.*?)\*/g, '<em>$1</em>')
  .replace(/^- (.*?)$/gm, '<li>$1</li>')
  .replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>')
  .replace(/^\d+\. (.*?)$/gm, '<li>$1</li>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br/>');

const fullHTML = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>Meeting Brief - ${data.companyName}</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 13px; color: #1a1a2e; line-height: 1.7; padding: 40px 50px; }
  .header { background: linear-gradient(135deg, #0f3460 0%, #16213e 100%); color: white; padding: 28px 32px; border-radius: 12px; margin-bottom: 32px; }
  .header h1 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
  .header .meta { font-size: 12px; opacity: 0.85; display: flex; gap: 24px; flex-wrap: wrap; margin-top: 12px; }
  .header .meta span { display: flex; align-items: center; gap: 6px; }
  .badge { background: #e94560; padding: 3px 10px; border-radius: 12px; font-size: 11px; font-weight: 600; }
  h1 { color: #0f3460; font-size: 20px; margin: 28px 0 12px; border-bottom: 3px solid #e94560; padding-bottom: 8px; }
  h2 { color: #0f3460; font-size: 16px; margin: 22px 0 10px; border-left: 4px solid #e94560; padding-left: 12px; }
  h3 { color: #16213e; font-size: 14px; margin: 16px 0 8px; }
  p { margin: 8px 0; color: #2d2d2d; }
  ul, ol { padding-left: 22px; margin: 8px 0; }
  li { margin-bottom: 5px; color: #2d2d2d; }
  strong { color: #0f3460; }
  .section { background: #f8f9ff; border-radius: 8px; padding: 16px 20px; margin: 12px 0; border-left: 3px solid #0f3460; }
  .footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #ddd; font-size: 11px; color: #888; text-align: center; }
  @media print { body { padding: 20px 30px; } .header { break-inside: avoid; } }
</style>
</head>
<body>
<div class="header">
  <h1>🧠 Meeting Preparation Brief</h1>
  <div class="meta">
    <span>🏢 <strong>${data.companyName}</strong></span>
    <span>👤 ${data.contactName}</span>
    <span>🎯 ${data.meetingPurpose}</span>
    <span>📅 ${now}</span>
    <span class="badge">AI Generated</span>
  </div>
</div>
${html}
<div class="footer">Generated by AI Meeting Prep Agent &nbsp;|&nbsp; Powered by Bhaskar Gorati — AI Automation Engineer &nbsp;|&nbsp; ${now}</div>
</body>
</html>`;

return [{ json: { ...data, htmlForPDF: fullHTML } }];

const error = $input.first().json;

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow: "AI Meeting Preparation Agent",
    status: "FAILED",
    failedNode: error.node?.name || "Unknown Node",
    errorMessage: error.message || error.error?.message || "Unknown Error",
    errorDetails: JSON.stringify(error, null, 2),
  }
}];
